typescript.starter:
// Добро пожаловать в песочницу TypeScript!
type User = { name: string; age: number };

function greet(user: User): string {
    return `Меня зовут ${user.name}, мне ${user.age} лет`;
}

const user: User = { name: "Артур", age: 100 };
console.log("Привет, мир!");
console.log(greet(user));

const nums: number[] = [1, 2, 3, 4, 5];
nums.forEach((n: number) => console.log(n, "в квадрате =", n ** 2));

java.starter:
public class Main {
    public static void main(String[] args) {
        // Java 8 в консоли Windows печатает латиницей — как в уроках курса
        String name = "Arthur";
        int age = 100;
        System.out.println("Hello, world!");
        System.out.println("Name: " + name + ", age: " + age);

        for (int i = 1; i <= 5; i++) {
            System.out.println(i + " squared = " + (i * i));
        }
    }
}

cpp.starter:
#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    string name = "Arthur";
    int age = 100;
    cout << "Hello, world!" << endl;
    cout << "Name: " << name << ", age: " << age << endl;

    vector<int> nums = {1, 2, 3, 4, 5};
    for (int n : nums) {
        cout << n << " squared = " << n * n << endl;
    }
    return 0;
}

