csharp.starter:
using System;
using System.Collections.Generic;

class Program {
    static void Main() {
        string name = "Артур";
        int age = 100;
        Console.WriteLine("Привет, мир!");
        Console.WriteLine($"Меня зовут {name}, мне {age} лет");

        var nums = new List<int> { 1, 2, 3, 4, 5 };
        foreach (int n in nums) {
            Console.WriteLine($"{n} в квадрате = {n * n}");
        }
    }
}

